import React, { Component } from 'react'
import { JobStyleWrapper } from './career.style'
import { Row, Col, Breadcrumb, Card } from 'antd'
import { imageUrls, Section5Content } from './content'
import AppFooter from '../../../components/Footer/footer'
import JobSearchBar from './JobSearchBar'
import NotFound from './noresultFound'
const { jobType, category } = imageUrls

class JobCategory extends Component {
  applyFormPage = data => {
    this.props.history.push('/career/form', { ...data })
  };
  homePage = () => {
    this.props.history.push({
      pathname: '/career'
    })
  }
  seeDetailsPage = (selectedPosition) => {
    let data = {}
    Section5Content.map((item, index) => {
      let { positionsArray } = item
      positionsArray.map(filterData => {
        if (filterData.position === selectedPosition.position) {
          data = {
            index,
            item,
            filterData
          }
        }
      })
    })
    this.props.history.push({
      pathname: '/career/vacancy-list/job-description',
      state: data
    })
  }

  render () {
    const { location, history } = this.props
    const content = location.state

    return (
      <div>
        <JobSearchBar
          className='marginT-auto'
          history={history}
          // routingFunction={routingFunction}
          showBackground
        />
        <JobStyleWrapper>
          <Row className='sectionDiv'>
            <Col span={24} className='marginB20'>
              <Breadcrumb className='padding20 font-size17'>
                <Breadcrumb.Item>
                  <span onClick={() => this.homePage()}>
                    Career
                  </span>
                </Breadcrumb.Item>

                {
                  !!content &&
                    content.length === 1 ? (
                      <Breadcrumb.Item>
                        <span className='text-yellow'>{content[0].category}</span>
                      </Breadcrumb.Item>
                    ) : (
                      <Breadcrumb.Item>
                        <span className='text-yellow'>Jobs</span>
                      </Breadcrumb.Item>
                    )}
              </Breadcrumb>
            </Col>
            {
              content && content.length > 0
                ? (content.map(item => (
                  <React.Fragment>
                    <Col span={24} className='flex-container marginB20'>
                      <div className='padding20'>
                        <img
                          src={item.logo}
                          alt='technology'
                          className='jobDetail-main-image'
                        />
                      </div>
                      <div className='padding20'>
                        <h2 className='text-yellow'>{item.category}</h2>
                      </div>
                    </Col>
                    <Col span={24} className='marginB20 flex-wrap'>
                      {item['positionsArray'].map((jobSearched, index) => (
                        <Col
                          xl={8}
                          lg={8}
                          md={12}
                          sm={12}
                          xs={24}
                          className='padding20'
                          index={index}
                        >
                          <Card className='custom-card card-no-padding body-flex'>
                            <div className='padding24 no-paddingB'>
                              <h2 className='text-yellow'>{jobSearched.position}</h2>
                              <ul className='custom-list'>
                                <li>{jobSearched.text}</li>
                              </ul>
                            </div>
                            <div className='padding24 marginT-auto no-paddingT'>
                              <hr className='custon-hr' />
                              <div className='flex-container'>
                                <div className='padding5'>
                                  <img
                                    src={category}
                                    alt='location'
                                    className='display_inlineB smaller-side-image'
                                  />
                                  <small className='display_inlineB color-fade font-mobile-13'>
                                    {jobSearched.jobLocation}
                                  </small>
                                </div>
                                <div className='padding5'>
                                  <img
                                    src={jobType}
                                    alt='type'
                                    className='display_inlineB smaller-side-image'
                                  />
                                  <small className='display_inlineB color-fade font-mobile-13'>
                                    {jobSearched.jobSpan}
                                  </small>
                                </div>
                              </div>
                            </div>
                            <Row type='flex'>
                              <Col
                                span={12}
                                className='text-center job-detail-button button-detail'
                                onClick={() => this.seeDetailsPage(jobSearched)}>
                                See Details
                              </Col>
                              <Col
                                span={12}
                                className='text-center job-detail-button button-apply'
                                onClick={() => this.applyFormPage(jobSearched)}
                              >
                                Apply
                              </Col>
                            </Row>
                          </Card>
                        </Col>
                      ))}
                    </Col>
                  </React.Fragment>
                )))
                : <NotFound />
            }
          </Row>
        </JobStyleWrapper>
        <AppFooter />
      </div>
    )
  }
}

JobCategory.propTypes = {}

export default JobCategory
